"""Run-local, model-selected source mappings. Code copies; the model interprets.

The little mapping language deliberately has no navigation or executable expressions.
A reusable plan has no interpreted constants: every value is grounded in a current
cell or an exact labelled line. Changed headers, duplicate labels and ragged rows
invalidate it. Unstructured prose can still use the ordinary fact schema.
"""
import hashlib
import json
import re
from dataclasses import dataclass, field

REF = re.compile(r"\[(?:f\d+)?e\d+\]")


class MappingError(ValueError):
    pass


@dataclass
class Sources:
    text: str
    lines: list[str] = field(init=False)
    tables: dict[str, list[list[str]]] = field(init=False)

    def __post_init__(self):
        self.lines = self.text.splitlines()
        self.tables = {}
        current = []
        for line in self.lines + [""]:
            if line.strip().startswith("| ") and line.rstrip().endswith(" |"):
                # A pipe inside a value is ambiguous: reject ragged tables below.
                current.append([c.strip() for c in line.strip()[1:-1].split("|")])
            elif current:
                self.tables[f"T{len(self.tables)}"] = current
                current = []

    def annotated(self) -> str:
        tables = {k: {"header": v[0], "rows": len(v)} for k, v in self.tables.items()}
        return "TABLE SOURCES " + json.dumps(tables, ensure_ascii=False) + "\n" + "\n".join(
            f"L{i}: {line}" for i, line in enumerate(self.lines))

    def fingerprint(self) -> str:
        # Keep heading context as well as ordered headers: two equal column names
        # under different stock/price sections must not share mappings.
        headers = {k: [REF.sub("", c) for c in v[0]] for k, v in self.tables.items()}
        headings = [REF.sub("", l.strip()) for l in self.lines if l.lstrip().startswith("#")]
        return hashlib.sha256(json.dumps([headers, headings], ensure_ascii=False).encode()).hexdigest()

    def line(self, ref: str) -> str:
        if not re.fullmatch(r"L\d+", str(ref)):
            raise MappingError("unknown source node")
        index = int(ref[1:])
        if index >= len(self.lines):
            raise MappingError("source disappeared")
        return self.lines[index]


@dataclass
class ExtractionMap:
    kind: str
    program: dict
    signature: str
    reusable: bool = False
    locale: str | None = None

    @classmethod
    def from_reply(cls, kind: str, reply: dict, source: Sources):
        program = reply.get("data")
        if not isinstance(program, dict):
            raise MappingError("missing data object")
        reusable = reply.get("reuse") is True and _grounded(program)
        # Positional line pointers are safe only for this one page.
        return cls(kind, program, source.fingerprint(), reusable, reply.get("locale"))

    def apply(self, source: Sources) -> dict:
        if source.fingerprint() != self.signature:
            raise MappingError("source structure changed")
        result = _copy(self.program, source)
        if not isinstance(result, dict) or not result:
            raise MappingError("empty extraction")
        return result


def _grounded(node) -> bool:
    if isinstance(node, dict):
        if "$cell" in node:
            return set(node) <= {"$cell", "locale"} and isinstance(node["$cell"], int) and node["$cell"] >= 0
        if "$line" in node:
            return set(node) == {"$line"} and isinstance(node["$line"], str) and bool(node["$line"].strip())
        if "$rows" in node:
            return set(node) <= {"$rows", "header", "fields"} and isinstance(node.get("header"), list) and _grounded(node.get("fields"))
        return bool(node) and all(_grounded(v) for v in node.values())
    if isinstance(node, list):
        return bool(node) and all(_grounded(v) for v in node)
    return False  # model-interpreted literals are never reused on another page


def _copy(node, source: Sources, row: list[str] | None = None):
    if isinstance(node, dict):
        if "$source" in node:
            refs = node["$source"]
            refs = [refs] if isinstance(refs, str) else refs
            if not isinstance(refs, list) or not refs:
                raise MappingError("empty source reference")
            return "\n".join(source.line(r) for r in refs)
        if "$cell" in node:
            index = node["$cell"]
            if row is None or isinstance(index, bool) or not isinstance(index, int) or index < 0 or index >= len(row):
                raise MappingError("missing column")
            value = row[index]
            if node.get("locale"):
                if node["locale"] not in ("de-DE", "en-US"):
                    raise MappingError("unsupported locale")
                value += " (" + node["locale"] + ")"
            return value
        if "$line" in node:
            label = node["$line"]
            hits = [l.strip()[len(label):].strip() for l in source.lines if l.strip().startswith(label)]
            if len(hits) != 1 or not hits[0]:
                raise MappingError("missing or ambiguous labelled value")
            return hits[0]
        if "$rows" in node:
            rows = source.tables.get(node["$rows"])
            header = node.get("header")
            if not rows or rows[0] != header or len(rows) < 2 or any(len(r) != len(header) for r in rows):
                raise MappingError("table headers or row width changed")
            fields = node.get("fields")
            if not isinstance(fields, dict) or not fields:
                raise MappingError("no column bindings")
            return [_copy(fields, source, r) for r in rows[1:]]
        return {k: _copy(v, source, row) for k, v in node.items()}
    if isinstance(node, list):
        return [_copy(v, source, row) for v in node]
    return node


