COPIED_FIELDS = {"mail_message": ("body",), "requirements": ("original_text",),
                 "materials": ("description",), "clarifications": ("question", "answer"),
                 "positions": ("short_text",)}


def compact_schema(kind: str, schema: str) -> str:
    for key in COPIED_FIELDS.get(kind, ()):
        schema = re.sub(r'("' + re.escape(key) + r'"\s*:\s*)"[^"]*"',
                        r'\1{"$source": ["source line IDs for the original text"]}', schema)
    return schema
