"""A compact, validated transport for the existing model-selected tools."""
import json
import math


def signature(schema):
    if 'enum' in schema:
        return '|'.join(json.dumps(value, ensure_ascii=False) for value in schema['enum'])
    kind = schema.get('type', 'object')
    if kind == 'object' and schema.get('properties'):
        required = set(schema.get('required', []))
        return '{' + ','.join(key + ('' if key in required else '?') + ':' + signature(value)
                             for key, value in schema['properties'].items()) + '}'
    if kind == 'array':
        limit = f";max={schema['maxItems']}" if 'maxItems' in schema else ''
        return '[' + signature(schema.get('items', {})) + limit + ']'
    return kind


def protocol(tools):
    schemas = {tool['function']['name']: tool['function']['parameters'] for tool in tools}
    manual = '\n'.join(f"{tool['function']['name']}{signature(tool['function']['parameters'])}: "
                       f"{tool['function'].get('description', '')}" for tool in tools)
    dispatch = {'type': 'function', 'function': {'name': 'dispatch',
        'description': 'Execute one tool from TOOL SIGNATURES, with its arguments. Steps batches selected actions.',
        'parameters': {'type': 'object', 'properties': {
            'tool': {'type': 'string', 'enum': list(schemas)}, 'args': {'type': 'object'}},
            'required': ['tool', 'args']}}}
    return [dispatch], manual, schemas


def validate(value, schema, path='args'):
    kind = schema.get('type')
    types = {'object': dict, 'array': list, 'string': str, 'boolean': bool, 'integer': int, 'number': (int, float)}
    if kind in types and (not isinstance(value, types[kind]) or kind in ('integer', 'number') and isinstance(value, bool)):
        raise ValueError(f'{path} needs {kind}')
    if kind == 'number' and not math.isfinite(value):
        raise ValueError(f'{path} needs a finite number')
    if 'enum' in schema and value not in schema['enum']:
        raise ValueError(f'{path} is not an allowed value')
    if isinstance(value, dict):
        for key in schema.get('required', []):
            if key not in value:
                raise ValueError(f'{path}.{key} is required')
        for key, subschema in schema.get('properties', {}).items():
            if key in value:
                validate(value[key], subschema, f'{path}.{key}')
    if isinstance(value, list):
        if 'maxItems' in schema and len(value) > schema['maxItems']:
            raise ValueError(f'{path} exceeds batch limit')
        for index, item in enumerate(value):
            validate(item, schema.get('items', {}), f'{path}[{index}]')


def decode(command, schemas):
    if not isinstance(command, dict) or command.get('tool') not in schemas:
        raise ValueError('choose an available tool from TOOL SIGNATURES')
    name, args = command['tool'], command.get('args')
    if not isinstance(args, dict):
        raise ValueError('args must be an object')
    validate(args, schemas[name])
    return name, args
