def test_compact_command_rejects_missing_or_invalid_dependent_actions():
    from rfq.agent import commands
    from rfq.agent.explorer import compact_tools, explorer_tools
    tools = compact_tools(explorer_tools())
    dispatch, manual, schemas = commands.protocol(tools)
    assert commands.decode({'tool': 'select', 'args': {'ref': 'e2', 'option': '4', 'then_click': 'e3'}}, schemas) == (
        'select', {'ref': 'e2', 'option': '4', 'then_click': 'e3'})
    assert 'select{' in manual and 'then_click?' in manual
    for command in ({'tool': 'invented', 'args': {}}, {'tool': 'select', 'args': {'ref': 'e2'}},
                    {'tool': 'check', 'args': {'ref': 'e2', 'checked': 'true'}},
                    {'tool': 'select', 'args': {'ref': 2, 'option': '4'}}):
        with pytest.raises(ValueError):
            commands.decode(command, schemas)
    assert dispatch[0]['function']['name'] == 'dispatch'
